import {BrowserClient,BrowserEnrollmentKey,BrowserEnrollmentStore,BrowserSdkClient,browserOperationKinds,sdkId} from '/sdk/browser.js';
const trace=[],begin=BrowserClient.prototype.begin;
BrowserClient.prototype.begin=function(...args){trace.push({request:args[0],operation:args[2]?.operation_id});return begin.apply(this,args);};
const assert=(value,label)=>{if(!value)throw Error(label);};
const decode=s=>Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),v=>v.charCodeAt(0));
async function post(path,value){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',body:JSON.stringify(value)});assert(response.ok,'owned fixture backend');return response.json();}
globalThis.runBrowserFixture=async cfg=>{try{
 const key=await crypto.subtle.importKey('raw',decode(cfg.server_public_raw),{name:'Ed25519'},true,['verify']),server={key,keyId:cfg.server_keyid,algorithm:'EdDSA',notBefore:cfg.server_not_before,expiresAt:cfg.server_expires_at},pins=[{algorithm:'sha-256',value:decode(cfg.certificate_sha256)}],vault=new BrowserEnrollmentStore('connect-decisions-browser'),byPath={},device='decision-device-'+cfg.suffix,now=Math.floor(Date.now()/1000),options={timeoutMs:5000},recipients=[cfg.identity_id,cfg.recipient_id];
 for(const transport of ['webtransport','wss-webrtc']){
  const name=cfg.suffix+'-'+transport,key=await BrowserEnrollmentKey.generate('EdDSA');
  await vault.prepare(name,cfg.api_origin,{operation_id:'approve-'+name,completion_operation_id:'claim-'+name,identity_id:cfg.identity_id,device:{id:device,kind:'browser',platform:'owned-Chrome'},key_id:'key-'+name,algorithm:key.algorithm,public_key:key.publicKey,transport,endpoint_address:location.origin+'/device/'+name,capabilities:['control','data'],browser_origin:location.origin,operations:['conversation.get','create','history','operation.cancel','operation.get','operation.reconcile','send'],recipients,credential_expires_at:now+300,challenge_expires_at:now+120},key);
  const offer=(await post('/decisions-approve',await vault.request(name))).result.Ok;await(await vault.acceptOffer(name,offer)).claim();byPath[transport]={name,contact:{url:transport==='webtransport'?cfg.wt_url:cfg.wss_url,server,...(transport==='webtransport'?{serverCertificateHashes:pins}:{})}};
 }
 const result={passed:true,direct_wt:0,bounded_wss_fallback:0,root_decisions:0,message_decisions:0,original_sources_unchanged:0,recovered_originals:0,unattributed_evidence_refused:0,revoked_decision_refused:0},saved=[];
 for(const path of ['webtransport','wss-webrtc']){
  const resolve=vault.resolveProfiles(byPath),resolutions=[],client=await BrowserSdkClient.connect({tenantId:'tnt_default',identityId:cfg.identity_id,deviceId:device,endpoints:{webtransport:path==='webtransport'?cfg.wt_url:cfg.unreachable_wt_url,'wss-webrtc':cfg.wss_url},timeoutMs:5000,attemptTimeoutMs:350,resolveEnrollment:context=>{resolutions.push(context.transport);return resolve(context);}}),suffix=cfg.suffix+'-'+path;
  try{
   assert(client.transport.selectedTransport===path&&JSON.stringify(resolutions)===JSON.stringify(path==='webtransport'?['webtransport']:['webtransport','wss-webrtc']),'bounded selected control transport');result[path==='webtransport'?'direct_wt':'bounded_wss_fallback']++;
   const createInput={policy:'persistent',participants:[sdkId(cfg.recipient_id)]},createId=sdkId('decision-room-'+suffix);sessionStorage.setItem('create-intent-'+suffix,JSON.stringify({input:createInput,operationId:createId}));const created=await client.conversations.create(createInput,{...options,operationId:createId}),room=(await created.wait(options)).value;
   const rootId=sdkId('root-cancel-'+suffix);sessionStorage.setItem('root-decision-'+suffix,JSON.stringify({operationId:rootId,target:created.referenceJson()}));const root=await created.cancel({...options,operationId:rootId}),rootValue=(await root.wait(options)).value;assert(Object.keys(root.reference.scope).length===0&&rootValue.target===createId&&rootValue.observedState==='completed'&&rootValue.disposition==='already_terminal','root decision observes the original terminal create');result.root_decisions++;
   const target=await room.participants.byIdentity(sdkId(cfg.recipient_id),options),input={messageId:sdkId('decision-message-'+suffix),to:{first:target.id,rest:[]},text:'owned decision '+path},sendId=sdkId('decision-send-'+suffix);sessionStorage.setItem('send-intent-'+suffix,JSON.stringify({conversationId:room.id,input,operationId:sendId}));const send=await room.send(input,{...options,operationId:sendId});await send.wait(options);
   const own=sdkId('message-cancel-'+suffix);sessionStorage.setItem('message-decision-'+suffix,JSON.stringify({operationId:own,target:send.referenceJson()}));const cancelled=await send.cancel({...options,operationId:own}),value=(await cancelled.wait(options)).value;assert(value.decision.operationId===own&&value.target===sendId&&value.observedState==='completed'&&value.disposition==='already_terminal'&&value.evidenceId===undefined&&cancelled.reference.scope.conversationId===room.id&&cancelled.reference.scope.connectionId===undefined,'decision and source IDs/scopes stay separate');result.message_decisions++;
   const reconcileInput={outcome:'completed',evidenceId:'unattributed-'+suffix},reconcileId=sdkId('reconcile-refused-'+suffix);sessionStorage.setItem('reconcile-intent-'+suffix,JSON.stringify({operationId:reconcileId,input:reconcileInput,target:send.referenceJson()}));let denied;try{await send.reconcile(reconcileInput,{...options,operationId:reconcileId});}catch(error){denied=error;}assert(denied?.kind==='authentication'&&denied?.certainty==='refused'&&denied?.operation.operationId===reconcileId,'caller outcome without attributed evidence cannot reconcile a target');result.unattributed_evidence_refused++;
   assert((await created.status(options)).state==='completed'&&(await send.status(options)).state==='completed'&&(await send.wait(options)).value.messageId===input.messageId,'completed sources are unchanged by decision/refusal');result.original_sources_unchanged++;
   sessionStorage.setItem('root-reference-'+suffix,JSON.stringify(root.referenceJson()));sessionStorage.setItem('message-reference-'+suffix,JSON.stringify(cancelled.referenceJson()));await client.reconnect({preferredTransport:path});for(const name of ['root','message']){const original=client.operations.restore(JSON.parse(sessionStorage.getItem(name+'-reference-'+suffix)),browserOperationKinds.operationCancel),receipt=(await original.wait(options)).value;assert(receipt.target===(name==='root'?createId:sendId)&&receipt.disposition==='already_terminal','restore observes the original durable decision without resubmitting');}result.recovered_originals++;saved.push(cancelled.referenceJson());
  }finally{client.close();}
 }
 const client=await BrowserSdkClient.connect({tenantId:'tnt_default',identityId:cfg.identity_id,deviceId:device,endpoints:{webtransport:cfg.wt_url},preferredTransport:'webtransport',timeoutMs:5000,resolveEnrollment:vault.resolveProfiles(byPath)});
 try{const original=client.operations.restore(saved[0],browserOperationKinds.operationCancel);await original.wait(options);const enrollment=await vault.load(byPath.webtransport.name);await post('/revoke',{enrollment_id:enrollment.offer.enrollment_id,operation_id:'revoke-decision-'+cfg.suffix});let denied;try{await original.wait(options);}catch(error){denied=error;}assert(denied&&['authentication','cancelled','transport-uncertain'].includes(denied.kind),'retired authority cannot deliver a cached decision result');let refused;try{await client.reconnect({preferredTransport:'webtransport'});}catch(error){refused=error;}assert(refused?.kind==='authentication'&&refused?.certainty==='refused','current original enrollment claim is refused');result.revoked_decision_refused++;}finally{client.close();}
 const count=kind=>trace.filter(v=>v.request===kind).length,mutations=trace.filter(v=>['conversation.create','message.send','operation.cancel','operation.reconcile'].includes(v.request));assert(count('conversation.create')===2&&count('message.send')===2&&count('operation.cancel')===4&&count('operation.reconcile')===2&&new Set(mutations.map(v=>v.operation)).size===10,'each source and explicit decision has its original ID; no hidden mutation replay');return {...result,source_mutations:4,decision_mutations:4,reconcile_attempts:2,credentials:2,devices:1,endpoints:2};
}catch(error){throw Error(String(error.stack??error)+'\n'+JSON.stringify(trace));}};
